        async function handleLogin() {
            const uInput = document.getElementById('login-user');
            const pInput = document.getElementById('login-pin');
            const u = uInput.value.trim().toLowerCase();
            const p = pInput.value.trim();
            const errorMsg = document.getElementById('login-error');
            const submitBtn = document.getElementById('btn-login-submit');

            if (!u || !p) {
                errorMsg.innerText = 'Ingresa usuario y PIN';
                errorMsg.classList.remove('hidden');
                return;
            }

            errorMsg.classList.add('hidden');
            submitBtn.disabled = true;
            submitBtn.innerText = 'Verificando...';

            if (u === AUTH_CEO_USER && p === AUTH_CEO_PIN) {
                currentUserRole = 'admin';
                try {
                    sessionStorage.setItem('priceStudioAuth', 'true');
                    sessionStorage.setItem('priceStudioRole', 'admin');
                } catch(e) {}
                applyRoleRestrictions();
                showMainMenu(true);
                submitBtn.disabled = false;
                submitBtn.innerText = 'Entrar al Sistema';
                return;
            }

            try {
                if (db) {
                    const snap = await db.collection('users')
                        .where('username', '==', u)
                        .where('pin', '==', p)
                        .get();

                    if (!snap.empty) {
                        currentUserRole = 'user';
                        try {
                            sessionStorage.setItem('priceStudioAuth', 'true');
                            sessionStorage.setItem('priceStudioRole', 'user');
                        } catch(e) {}
                        applyRoleRestrictions();
                        showHub(true);
                        submitBtn.disabled = false;
                        submitBtn.innerText = 'Entrar al Sistema';
                        return;
                    }
                }
            } catch (err) {
                console.error("Error consultando usuario:", err);
            }

            errorMsg.innerText = 'Usuario o PIN incorrecto';
            errorMsg.classList.remove('hidden');
            pInput.value = '';
            submitBtn.disabled = false;
            submitBtn.innerText = 'Entrar al Sistema';
        }

