        async function createNewUserInFirebase() {
            const u = document.getElementById('new-user-name').value.trim().toLowerCase();
            const p = document.getElementById('new-user-pin').value.trim();

            if (!u || p.length < 4) {
                alert('Ingresa un usuario y un PIN de al menos 4 dígitos.');
                return;
            }

            try {
                if (db) {
                    await db.collection('users').add({
                        username: u,
                        pin: p,
                        role: 'user',
                        createdAt: firebase.firestore.FieldValue.serverTimestamp()
                    });
                    document.getElementById('new-user-name').value = '';
                    document.getElementById('new-user-pin').value = '';
                    loadUsersFromFirebase();
                }
            } catch (e) {
                alert('Error al guardar usuario en la nube: ' + e.message);
            }
        }

        async function loadUsersFromFirebase() {
            const container = document.getElementById('users-list-container');
            if (!db) {
                container.innerHTML = `<span class="text-xs text-white/40 italic">Firebase offline</span>`;
                return;
            }

            try {
                const snap = await db.collection('users').get();
                usersListCloud = [];
                snap.forEach(doc => usersListCloud.push({ id: doc.id, ...doc.data() }));

                if (usersListCloud.length === 0) {
                    container.innerHTML = `<span class="text-xs text-white/40 italic">Aún no hay usuarios creados.</span>`;
                    return;
                }

                container.innerHTML = usersListCloud.map(u => `
                    <div class="inner-box px-3 py-2 rounded-lg text-xs flex justify-between items-center">
                        <div>
                            <span class="font-bold text-white">${u.username}</span>
                            <span class="text-white/40 font-mono ml-2">PIN: ${u.pin}</span>
                        </div>
                        <button type="button" onclick="deleteUserFromFirebase('${u.id}')" class="text-red-400 hover:text-red-300 font-bold">
                            Eliminar
                        </button>
                    </div>
                `).join('');
            } catch (e) {
                console.error("Error al cargar usuarios:", e);
            }
        }

