        // --- 5. TASA OFICIAL BCV ---
        async function fetchBCVRate() {
            const rateDisplay = document.getElementById('bcv-header-rate');
            const rateInput = document.getElementById('pay-bcv-rate');
            if (rateDisplay) rateDisplay.innerText = 'Consultando...';
            try {
                const response = await fetch('https://ve.dolarapi.com/v1/dolares/oficial');
                const data = await response.json();
                if (data && data.promedio) {
                    currentBCVRate = parseFloat(data.promedio);
                    if (rateDisplay) rateDisplay.innerText = `${currentBCVRate.toFixed(2)} Bs/$`;
                    if (rateInput) rateInput.value = currentBCVRate.toFixed(2);
                    updatePaymentConversion();
                    return;
                }
            } catch (err) {
                console.warn("No se pudo obtener BCV automático:", err);
            }
            if (rateDisplay) rateDisplay.innerText = 'Manual';
        }
        fetchBCVRate();

        // --- 6. DRAG & DROP, CLIC, CTRL+V Y OCR (MÓDULO PAGOS) ---
        function initCaptureEvents() {
            const dropzone = document.getElementById('capture-dropzone');
            if (!dropzone || dropzone.dataset.bound === 'true') return;
            dropzone.dataset.bound = 'true';

            ['dragenter', 'dragover'].forEach(name => {
                dropzone.addEventListener(name, (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    dropzone.classList.add('drag-over-active');
                });
            });

            ['dragleave', 'drop'].forEach(name => {
                dropzone.addEventListener(name, (e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    dropzone.classList.remove('drag-over-active');
                });
            });

            dropzone.addEventListener('drop', (e) => {
                const files = e.dataTransfer.files;
                if (files && files.length > 0 && files[0].type.startsWith('image/')) {
                    processCaptureFile(files[0]);
                }
            });
        }

        window.addEventListener('paste', (e) => {
            const payView = document.getElementById('payment-view');
            if (!payView || payView.style.display !== 'block') return;
            const items = (e.clipboardData || e.originalEvent.clipboardData).items;
            for (let item of items) {
                if (item.type.indexOf('image') !== -1) {
                    processCaptureFile(item.getAsFile());
                }
            }
        });

        function handleCaptureUpload(event) {
            const file = event.target.files && event.target.files[0];
            if (file) processCaptureFile(file);
        }

        function processCaptureFile(file) {
            const reader = new FileReader();
            reader.onload = function(evt) {
                currentCaptureDataUrl = evt.target.result;
                const preview = document.getElementById('capture-preview');
                const placeholder = document.getElementById('upload-placeholder');
                const changeBtn = document.getElementById('change-btn');

                if (preview) {
                    preview.src = currentCaptureDataUrl;
                    preview.classList.remove('hidden');
                }
                if (placeholder) placeholder.classList.add('hidden');
                if (changeBtn) changeBtn.classList.remove('hidden');

                analyzeCaptureOCR(currentCaptureDataUrl);
            };
            reader.readAsDataURL(file);
        }

        async function analyzeCaptureOCR(imageSrc) {
            const statusBox = document.getElementById('ocr-status');
            const statusText = document.getElementById('ocr-status-text');
            if (statusBox) statusBox.classList.remove('hidden');
            if (statusText) statusText.innerHTML = `Escaneando texto del capture...`;
            try {
                const result = await Tesseract.recognize(imageSrc, 'spa+eng');
                parseExtractedReceiptText(result.data.text || '');
                if (statusText) statusText.innerHTML = `<span class="text-accent">✓ Datos detectados</span>`;
            } catch (e) {
                if (statusText) statusText.innerHTML = `<span class="text-yellow-300">Verifica los datos manualmente</span>`;
            }
        }

        function getSelectedPayCurrency() {
            const checked = document.querySelector('input[name="pay-tasa"]:checked');
            return checked ? checked.value : 'USDT';
        }

        function setSelectedPayCurrency(val) {
            const radio = document.querySelector(`input[name="pay-tasa"][value="${val}"]`);
            if (radio) radio.checked = true;
        }

        function parseExtractedReceiptText(text) {
            const cleanText = text.replace(/\r/g, ' ');
            const lower = cleanText.toLowerCase();

            const isBinance = /binance|usdt|order id|id de orden|cripto/.test(lower);
            const isBolivares = /\bbs\.?(?=\s|\d|$)|\bbol[ií]vares\b|\bpago m[oó]vil\b|\bbanesco\b|\bmercantil\b|\bprovincial\b|\bbanco de venezuela\b|\bbdv\b|\bbnc\b/.test(lower);

            const methodSelect = document.getElementById('pay-method');
            if (isBinance && !isBolivares) {
                setSelectedPayCurrency('USDT');
                if (methodSelect) methodSelect.value = 'Binance Pay (USDT)';
            } else if (isBolivares) {
                setSelectedPayCurrency('Bs');
                if (methodSelect) methodSelect.value = /transferencia/.test(lower) ? 'Transferencia Bancaria' : 'Pago Móvil';
            }

            const refMatch = cleanText.match(/(?:referencia|ref|nro|operaci[oó]n|orden|order id)[:\s#.-]*([0-9]{6,22})/i) || cleanText.match(/\b([0-9]{8,20})\b/);
            if (refMatch && refMatch[1]) document.getElementById('pay-ref').value = refMatch[1];

            const amtMatch = cleanText.match(/(?:monto|total|cantidad|importe|bs\.?|usdt)[:\s-]*([0-9]{1,3}(?:[.,][0-9]{3})*[.,][0-9]{2})/i) || cleanText.match(/\b([0-9]{1,6}[.,][0-9]{2})\b/);
            if (amtMatch && amtMatch[1]) {
                let numStr = amtMatch[1].trim();
                if (numStr.includes('.') && numStr.includes(',')) {
                    numStr = numStr.lastIndexOf(',') > numStr.lastIndexOf('.') ? numStr.replace(/\./g, '').replace(',', '.') : numStr.replace(/,/g, '');
                } else if (numStr.includes(',')) {
                    numStr = numStr.replace(',', '.');
                }
                const parsed = parseFloat(numStr);
                if (!isNaN(parsed) && parsed > 0) document.getElementById('pay-amount').value = parsed.toFixed(2);
            }

            updatePaymentConversion();
        }

        function handleMethodChange() {
            const method = document.getElementById('pay-method').value;
            if (method.includes('USDT')) setSelectedPayCurrency('USDT');
            else if (method.includes('Bs') || method.includes('Pago Móvil') || method.includes('Transferencia')) setSelectedPayCurrency('Bs');
            updatePaymentConversion();
        }

        function updatePaymentConversion() {
            const cur = getSelectedPayCurrency();
            const amt = parseFloat(document.getElementById('pay-amount').value) || 0;
            const lbl = document.getElementById('pay-amount-label');
            const bcvBox = document.getElementById('bs-conversion-box');
            const rateInputEl = document.getElementById('pay-bcv-rate');
            const rateDisplay = document.getElementById('bcv-header-rate');
            const rate = parseFloat(rateInputEl?.value) || currentBCVRate || 1;

            if (bcvBox) bcvBox.classList.remove('hidden');

            if (rate > 0 && rateDisplay) {
                currentBCVRate = rate;
                rateDisplay.innerText = `${rate.toFixed(2)} Bs/$`;
            }

            if (cur === 'Bs') {
                if (lbl) lbl.innerText = "Monto de la Transacción (Bs)";
                document.getElementById('pay-usd-equiv').innerText = (rate > 0 ? (amt / rate) : 0).toFixed(2);
            } else {
                if (lbl) lbl.innerText = "Monto de la Transacción (USDT)";
                document.getElementById('pay-usd-equiv').innerText = amt.toFixed(2);
            }
            updatePaymentLiveDoc();
        }

        function updatePaymentLiveDoc() {
            const recInput = document.getElementById('pay-receipt-id');
            if (recInput && recInput.value) {
                document.getElementById('doc-id').textContent = recInput.value;
            }
            document.getElementById('doc-staff-name').textContent = document.getElementById('pay-staff').value || "Nombre del Staff";
            document.getElementById('doc-staff-role').textContent = document.getElementById('pay-staff-role').value || "Cargo / Rol";
            document.getElementById('doc-ref').textContent = document.getElementById('pay-ref').value || "N/A";
            document.getElementById('doc-method').textContent = document.getElementById('pay-method').value || "N/A";
            
            const d = document.getElementById('pay-date').value;
            if (d) {
                const [y, m, day] = d.split('-');
                document.getElementById('doc-date').textContent = `${day}/${m}/${y}`;
            }
            
            const p = document.getElementById('pay-project').value || "Proyecto General";
            const c = document.getElementById('pay-concept').value || "Sin descripción";
            const cur = getSelectedPayCurrency();
            const a = parseFloat(document.getElementById('pay-amount').value) || 0;
            const sym = cur === 'Bs' ? 'Bs. ' : '$';

            document.getElementById('doc-items-list').innerHTML = `<div class="flex justify-between items-center"><div class="text-gray-800 text-xs"><b>${p}</b> - ${c}</div><div class="font-medium text-xs font-mono">${sym}${a.toFixed(2)}</div></div>`;
            document.getElementById('doc-total').textContent = `${sym}${a.toFixed(2)}`;
        }

        function resetPaymentForm() {
            currentCaptureDataUrl = null;
            const uploadInput = document.getElementById('capture-upload');
            if (uploadInput) uploadInput.value = '';
            const preview = document.getElementById('capture-preview');
            if (preview) { preview.src = ''; preview.classList.add('hidden'); }
            const placeholder = document.getElementById('upload-placeholder');
            if (placeholder) placeholder.classList.remove('hidden');
            const changeBtn = document.getElementById('change-btn');
            if (changeBtn) changeBtn.classList.add('hidden');
            const ocrStatus = document.getElementById('ocr-status');
            if (ocrStatus) ocrStatus.classList.add('hidden');

            document.getElementById('pay-date').value = getLocalDateString();
            const staffDropdown = document.getElementById('staff-select-dropdown');
            if (staffDropdown) staffDropdown.value = '';
            handleStaffDropdownChange('');
            const newId = Math.floor(1000 + Math.random() * 9000);
            document.getElementById('doc-id').textContent = newId;
            if (document.getElementById('pay-receipt-id')) document.getElementById('pay-receipt-id').value = newId;

            ['pay-project', 'pay-concept', 'pay-ref', 'pay-amount'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.value = '';
            });
            updatePaymentConversion();
        }

