        // --- 7. CÁLCULOS DEL TABULADOR ---
        let currentItems = [];
        let currentData = {};

        function stepQty(inputId, delta) {
            const el = document.getElementById(inputId);
            if (!el) return;
            const current = parseInt(el.value) || 0;
            const next = Math.max(0, current + delta);
            el.value = next === 0 ? '' : next;
            calculateTotal();
        }

        function syncActiveServiceCards() {
            const pairs = [
                ['card-rrss', 'rrss-qty'],
                ['card-carrusel', 'carrusel-qty'],
                ['card-reel', 'reel-qty'],
                ['card-storie', 'storie-qty'],
                ['card-photo', 'photo-qty'],
                ['card-pauta', 'pauta-qty']
            ];
            pairs.forEach(([cardId, inputId]) => {
                const card = document.getElementById(cardId);
                const val = parseInt(document.getElementById(inputId)?.value) || 0;
                if (card) card.classList.toggle('service-card-active', val > 0);
            });
        }

        function calculateTotal() {
            currentItems = [];
            let subtotalNeto = 0;           
            let subtotalPassThrough = 0;    

            const addLine = (name, qty, price, isPassThrough = false) => {
                const totalLine = qty * price;
                if (isPassThrough) subtotalPassThrough += totalLine;
                else subtotalNeto += totalLine;
                currentItems.push({ name, qty, price, total: totalLine, isPassThrough });
            };

            const getVal = (id) => {
                const el = document.getElementById(id);
                if (!el) return 0;
                let val = parseInt(el.value) || 0;
                return val < 0 ? 0 : val;
            };

            if (getVal('rrss-qty') > 0) {
                const sel = document.getElementById('rrss-type').value;
                const p = sel === 'custom' ? (parseFloat(document.getElementById('rrss-type-custom').value) || 0) : parseFloat(sel);
                addLine(`Diseño RRSS (${sel === 'custom' ? 'Personalizado' : (p === 3 ? 'Standard' : 'VIP')})`, getVal('rrss-qty'), p);
            }
            if (getVal('carrusel-qty') > 0) addLine('Carrusel', getVal('carrusel-qty'), 7);
            if (getVal('reel-qty') > 0) {
                const sel = document.getElementById('reel-type').value;
                const p = sel === 'custom' ? (parseFloat(document.getElementById('reel-type-custom').value) || 0) : parseFloat(sel);
                addLine(`Reel (${sel === 'custom' ? 'Personalizado' : (p === 5 ? 'Standard' : 'VIP')})`, getVal('reel-qty'), p);
            }
            if (getVal('storie-qty') > 0) addLine('Storie', getVal('storie-qty'), 1);
            if (getVal('photo-qty') > 0) {
                const sel = document.getElementById('photo-type').value;
                const p = sel === 'custom' ? (parseFloat(document.getElementById('photo-type-custom').value) || 0) : parseFloat(sel);
                addLine(`Edición Fotos (${sel === 'custom' ? 'Personalizado' : (p === 10 ? 'Standard' : 'VIP')})`, getVal('photo-qty'), p);
            }
            if (getVal('pauta-qty') > 0) {
                const sel = document.getElementById('pauta-type').value;
                const p = sel === 'custom' ? (parseFloat(document.getElementById('pauta-type-custom').value) || 0) : parseFloat(sel);
                addLine(`Pauta (${sel === 'custom' ? 'Personalizado' : (p === 10 ? 'Standard' : 'VIP')})`, getVal('pauta-qty'), p);
            }

            ['est-gestion', 'est-informe', 'est-plan', 'est-segmentacion', 'est-meta'].forEach(id => {
                const cb = document.getElementById(id);
                if (cb && cb.checked) addLine(cb.parentElement.querySelector('span').innerText, 1, parseFloat(cb.value));
            });

            const processOp = (id, name, isPassThrough) => {
                const selectEl = document.getElementById(id);
                if (!selectEl) return;
                const sel = selectEl.value;
                const p = sel === 'custom' ? (parseFloat(document.getElementById(id + '-custom').value) || 0) : (parseFloat(sel) || 0);
                if (p > 0) addLine(`${name}${sel === 'custom' ? ' (Personalizado)' : ''}`, 1, p, isPassThrough);
            };

            processOp('op-modelo', 'Modelo', false);               
            processOp('op-locucion', 'Locución / Voz', false);     
            processOp('op-produccion', 'Producción / POP', false); 
            processOp('op-traslados', 'Traslados', true); 
            processOp('op-utileria', 'Utilería / Locación', true);   

            syncActiveServiceCards();

            document.getElementById('summary-items').innerHTML = currentItems.map(item => `
                <div class="flex justify-between items-center py-1.5 border-b border-white/5 last:border-0 ${item.isPassThrough ? 'text-accent' : ''}">
                    <div class="flex items-center gap-2 pr-2">
                        <span class="font-mono text-[10px] font-bold px-1.5 py-0.5 rounded bg-white/10 text-white/90">${item.qty}x</span>
                        <span class="truncate">${item.name}</span>
                    </div>
                    <span class="font-mono font-medium shrink-0">$${item.total.toFixed(2)}</span>
                </div>
            `).join('') || '<p class="text-white/30 italic text-center py-10">Selecciona servicios a la izquierda para armar la cotización</p>';
            
            let totalBaseGeneral = subtotalNeto + subtotalPassThrough;
            document.getElementById('subtotal-neto').innerText = totalBaseGeneral.toFixed(2);

            let marginInput = currentUserRole === 'user' ? 50 : (parseFloat(document.getElementById('global-margin').value) || 0);
            document.getElementById('margin-display').innerText = marginInput;
            
            let totalVenta = 0, gananciaTotal = 0;
            if (subtotalNeto > 0) gananciaTotal = subtotalNeto * (marginInput / 100);
            if (totalBaseGeneral > 0) totalVenta = totalBaseGeneral + gananciaTotal;

            document.getElementById('total-venta').innerText = totalVenta.toFixed(2);
            document.getElementById('total-ganancia').innerText = gananciaTotal.toFixed(2);

            const distCEO = gananciaTotal * 0.40;
            const distAhorro = gananciaTotal * 0.20;
            const distReinv = gananciaTotal * 0.20;
            const distCapital = gananciaTotal * 0.20;

            document.getElementById('dist-ceo').innerText = distCEO.toFixed(2);
            document.getElementById('dist-ahorro').innerText = distAhorro.toFixed(2);
            document.getElementById('dist-reinv').innerText = distReinv.toFixed(2);
            document.getElementById('dist-capital').innerText = distCapital.toFixed(2);

            currentData = {
                subtotal: totalBaseGeneral.toFixed(2),
                venta: totalVenta.toFixed(2),
                ganancia: gananciaTotal.toFixed(2),
                ceo: distCEO.toFixed(2),
                ahorro: distAhorro.toFixed(2),
                reinv: distReinv.toFixed(2),
                capital: distCapital.toFixed(2),
                margen: marginInput
            };
        }

        function toggleCustom(idStr) {
            const select = document.getElementById(idStr);
            const customInput = document.getElementById(idStr + '-custom');
            if (select.value === 'custom') customInput.classList.remove('hidden');
            else { customInput.classList.add('hidden'); customInput.value = ''; }
        }

        function showResetModal() { document.getElementById('reset-modal').style.display = 'flex'; }
        function hideResetModal() { document.getElementById('reset-modal').style.display = 'none'; }
        function executeReset() {
            hideResetModal();
            ['rrss-qty', 'carrusel-qty', 'reel-qty', 'storie-qty', 'photo-qty', 'pauta-qty'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.value = '';
            });
            ['rrss-type-custom', 'reel-type-custom', 'photo-type-custom', 'pauta-type-custom', 'op-modelo-custom', 'op-locucion-custom', 'op-produccion-custom', 'op-traslados-custom', 'op-utileria-custom'].forEach(id => {
                const el = document.getElementById(id);
                if (el) { el.value = ''; el.classList.add('hidden'); }
            });
            ['rrss-type', 'reel-type', 'photo-type', 'pauta-type'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.selectedIndex = 0;
            });
            ['op-modelo', 'op-locucion', 'op-produccion', 'op-traslados', 'op-utileria'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.value = '0';
            });
            ['est-gestion', 'est-informe', 'est-plan', 'est-segmentacion', 'est-meta'].forEach(id => {
                const cb = document.getElementById(id);
                if (cb) cb.checked = false;
            });
            calculateTotal();
        }

        // --- 8. EXPORTACIONES A PDF ---
        function verificarImagenesAntesDePDF(container) {
            const imgs = Array.from(container.querySelectorAll('img.pdf-brand-logo, img.pdf-wait-img'));
            return Promise.all(imgs.map(img => {
                return new Promise(resolve => {
                    if (img.complete && img.naturalWidth > 0) resolve();
                    else {
                        img.onload = () => resolve();
                        img.onerror = () => {
                            if (!img.classList.contains('pdf-brand-logo')) { resolve(); return; }
                            const fallback = document.createElement('div');
                            fallback.style.cssText = 'display:inline-flex; align-items:center; justify-content:center; background:#dc2626; color:#ffffff; font-weight:800; font-size:11px; padding:6px 12px; border-radius:6px; border:1px solid #f87171; letter-spacing:0.05em;';
                            fallback.innerText = 'FALTA LOGO';
                            img.replaceWith(fallback);
                            resolve();
                        };
                    }
                });
            }));
        }

