        // --- 9. GESTIÓN DE TEMA (DARK / LIGHT CREMA-ROJO) ---
        function applyTheme(theme) {
            const isLight = theme === 'light';
            document.body.classList.toggle('light-theme', isLight);

            const dot = document.getElementById('theme-toggle-dot');
            const label = document.getElementById('theme-toggle-label');
            if (dot && label) {
                dot.style.backgroundColor = isLight ? '#03120e' : '#DC2626';
                label.innerText = isLight ? 'DARK MODE' : 'CREAM / RED';
            }

            document.querySelectorAll('img[alt="Bloom Studio"]').forEach(img => {
                img.src = isLight ? 'logo-b.svg' : 'Ver 2 w.svg';
            });
        }

        function toggleTheme() {
            const isCurrentlyLight = document.body.classList.contains('light-theme');
            const nextTheme = isCurrentlyLight ? 'dark' : 'light';
            try { localStorage.setItem('priceStudioTheme', nextTheme); } catch (e) {}
            applyTheme(nextTheme);
        }

        try {
            const savedTheme = localStorage.getItem('priceStudioTheme') || 'dark';
            applyTheme(savedTheme);
        } catch (e) {}

        initCaptureEvents();
        initStaffFirestoreListener();
        checkSession();
